import{_ as n,a0 as m,w as s,s as p,ao as o,I as e,a1 as l,A as i,x as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse('{"title":"Linux上有哪些好的终端模拟器? | LCTT x X-CMD","titleTemplate":false,"description":"Linux上有哪些好的终端模拟器? | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux上有哪些好的终端模拟器? | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux上有哪些好的终端模拟器? | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/20140529 What is a good terminal emulator on Linux","title":"Linux上有哪些好的终端模拟器?","tag":"201406","desc":""},"relativePath":"201406/20140529 What is a good terminal emulator on Linux.md","filePath":"[post].md"}'),_={name:"201406/20140529 What is a good terminal emulator on Linux.md"};function d(h,a,u,f,x,T){const r=m("Link");return s(),p("div",null,[a[14]||(a[14]=o('<h1 id="linux上有哪些好的终端模拟器" tabindex="-1">Linux上有哪些好的终端模拟器? <a class="header-anchor" href="#linux上有哪些好的终端模拟器" aria-label="Permalink to “Linux上有哪些好的终端模拟器?”">​</a></h1><p>一个好的终端模拟器是一个选择Linux而不是Windows或Mac的充分理由，任何Linux的资深用户都会同意这点。通过使用shell，用户可以完成在图形环境下不可能或者太重复的任务。但是终端模拟器的选择是非常重要的，因为它会成为你使用最多的程序。我会尝试列出在Linux上好的终端模拟器的清单，从经典的到奇特的，但是它们都是有效率且独特的。</p><p>如果你认为还有好的终端程序在这里没有提到，请在评论区让我们知道。这里列出了许多，大多数是值得你了解一下。</p><h3 id="_1-gnome-terminal" tabindex="-1">1. Gnome-terminal <a class="header-anchor" href="#_1-gnome-terminal" aria-label="Permalink to “1. Gnome-terminal”">​</a></h3><p><img src="https://farm4.staticflickr.com/3699/14100905190_478812cae2_z.jpg" alt=""></p><p>让我们先从“经典”终端开始，对于Gnome而言，Gnome-terminal和Gnome一样经典。它支持多用户配置，标签，文本大小调整，背景转换和高度定制。如它名字暗示的那样，它适用于Gnome环境。</p><h3 id="_2-konsole" tabindex="-1">2. Konsole <a class="header-anchor" href="#_2-konsole" aria-label="Permalink to “2. Konsole”">​</a></h3><p><img src="https://farm3.staticflickr.com/2897/14101006647_ec13565200_z.jpg" alt=""></p><p>同样大名鼎鼎，Konsole在KDE环境下等同于Gnome-terminal。Konsole额外支持的一点是分割视图和书签目录。</p><h3 id="_3-xfce-terminal" tabindex="-1">3. (Xfce) terminal <a class="header-anchor" href="#_3-xfce-terminal" aria-label="Permalink to “3. (Xfce) terminal”">​</a></h3><p><img src="https://farm3.staticflickr.com/2928/14100857759_fa29cc968e_z.jpg" alt=""></p><p>Xfce用户同样有他们的Xfce4终端。这个项目的目的是制造一个在外观上相似Gnome-terminal的产品，但是更少占用资源需求。它是高端定制化的，虽然没有用户配置功能或者透明背景。</p><h3 id="_4-lxterminal" tabindex="-1">4. LXTerminal <a class="header-anchor" href="#_4-lxterminal" aria-label="Permalink to “4. LXTerminal”">​</a></h3>',13)),e("p",null,[l(r,{href:"https://www.flickr.com/photos/xmodulo/14100905020/"},{default:i(()=>[...a[0]||(a[0]=[e("img",{src:"https://farm6.staticflickr.com/5569/14100905020_dd2b3e830e_z.jpg",alt:""},null,-1)])]),_:1})]),a[15]||(a[15]=o('<p>其目标是为了成为桌面环境下的最有名的终端，LXTerminal是为LXDE环境设计的。如你所能想到的，它甚至比xfce-terminal更轻量快速，去除了复杂的自定义和高级选项，只保持了标签功能。</p><h3 id="_5-terminator" tabindex="-1">5. Terminator <a class="header-anchor" href="#_5-terminator" aria-label="Permalink to “5. Terminator”">​</a></h3><p><img src="https://farm4.staticflickr.com/3726/14100980857_1591317b8a_z.jpg" alt=""></p><p>现在让我们看看终端模拟器中的劳斯莱斯，Terminator是这些终端里面功能最完备的一款，它包括了标签、水平和垂直分割视图、截屏、用户配置、插件、布局管理。可能还有一些你永远都用不到的选项。它的缺点是太大和大量的资源消耗，这些就是你付出的代价。</p><h3 id="_6-tilda" tabindex="-1">6. Tilda <a class="header-anchor" href="#_6-tilda" aria-label="Permalink to “6. Tilda”">​</a></h3>',5)),e("p",null,[l(r,{href:"https://www.flickr.com/photos/xmodulo/14284203351/"},{default:i(()=>[...a[1]||(a[1]=[e("img",{src:"https://farm6.staticflickr.com/5585/14284203351_2c25a33cb4_z.jpg",alt:""},null,-1)])]),_:1})]),a[16]||(a[16]=o('<p>这里还有一款完全不同的一款终端，它称为“下拉”式。如果你喜欢你的终端总是一键可达，也许你会喜欢下面提到的三个特点。首先，Tilda是一个典型的下拉式终端；它不依赖于环境并且非常轻量；你可以设置透明度或者甚至是不同的背景，并且选择出现在屏幕的那个边。除去这些，不要期待太复杂的功能，比如标签或者分割视图。Tilda只做一件事：在你需要的时候快速显示出来。</p><h3 id="_7-guake" tabindex="-1">7. Guake <a class="header-anchor" href="#_7-guake" aria-label="Permalink to “7. Guake”">​</a></h3><p><img src="https://farm4.staticflickr.com/3733/14285529772_aa824b5e39_z.jpg" alt=""></p><p>如果喜欢Tilda的方式，而且希望与Gnome结合更紧密，你应该试试Guake。在功能方面，它多多少少与Tilda相似。两者之间最大的不同是Guake更美观。</p><h3 id="_8-yakuake" tabindex="-1">8. Yakuake <a class="header-anchor" href="#_8-yakuake" aria-label="Permalink to “8. Yakuake”">​</a></h3>',5)),e("p",null,[l(r,{href:"https://www.flickr.com/photos/xmodulo/14100857589/"},{default:i(()=>[...a[2]||(a[2]=[e("img",{src:"https://farm6.staticflickr.com/5274/14100857589_142fdc4153_z.jpg",alt:""},null,-1)])]),_:1})]),a[17]||(a[17]=o('<p>KDE用户当然也不会被遗忘，他们有Yakuake，它基本上就是KDE环境下的Guake的替代品。它和Quake功能一样，除了还有标签化接口和用户配置。</p><h3 id="_9-terra" tabindex="-1">9. Terra <a class="header-anchor" href="#_9-terra" aria-label="Permalink to “9. Terra”">​</a></h3><p><img src="https://farm4.staticflickr.com/3700/14307721343_0e55878bb0_z.jpg" alt=""></p><p>对于既喜欢Terminator，也喜欢下拉式的资深用户而言，我估计Terra是最好的。介于Guake和Terminator之间，Terra在下拉式中支持分割视图和标签。</p><h3 id="_10-rxvt" tabindex="-1">10. rxvt <a class="header-anchor" href="#_10-rxvt" aria-label="Permalink to “10. rxvt”">​</a></h3><p><img src="https://farm3.staticflickr.com/2916/14307721303_805fe977ce_o.png" alt=""></p><p>如果你的目标是尽可能的轻量，并且你希望类似xterm，那么rxvt就是为你设计的。它没有标签和自定义，没有分割视图，没有任何东西，要极轻量就用rxvt。如果有时你只需要刚好够的功能，那么rxvt就是为你提供的。</p><h3 id="_11-sakura" tabindex="-1">11. Sakura <a class="header-anchor" href="#_11-sakura" aria-label="Permalink to “11. Sakura”">​</a></h3><p><img src="https://farm4.staticflickr.com/3823/14287031834_d8a5ac966f_z.jpg" alt=""></p><p>作为一款并不有名的终端模拟器，Sakura基于GTK但是并不需要完整的Gnome环境。不像rxvt，Sakura有一些额外的功能，像标签和颜色自定义，但是它尝试着保持简单和基本。因此如果你想要一款不针对特定环境的基础终端，Sakura可能是你想要的。</p><h3 id="_12-terminology" tabindex="-1">12. Terminology <a class="header-anchor" href="#_12-terminology" aria-label="Permalink to “12. Terminology”">​</a></h3><p><img src="https://farm4.staticflickr.com/3706/14264408226_a0223861ae_z.jpg" alt=""></p><p>这里面最奇异的终端是Terminology。它原本是为Enlightment设计的，它包括了目前我们看到的常规功能，并且还有我之前没有见过的功能。比如，直接在终端中播放流媒体，以及在文件列表中显示略缩图。</p><hr>',14)),e("p",null,[a[4]||(a[4]=t("via: ",-1)),l(r,{href:"http://xmodulo.com/2014/05/good-terminal-emulator-linux.html"},{default:i(()=>[...a[3]||(a[3]=[t("http://xmodulo.com/2014/05/good-terminal-emulator-linux.html",-1)])]),_:1})]),e("p",null,[a[7]||(a[7]=t("译者：",-1)),l(r,{href:"https://github.com/geekpi"},{default:i(()=>[...a[5]||(a[5]=[t("geekpi",-1)])]),_:1}),a[8]||(a[8]=t(" 校对：",-1)),l(r,{href:"https://github.com/wxy"},{default:i(()=>[...a[6]||(a[6]=[t("wxy",-1)])]),_:1})]),e("p",null,[a[11]||(a[11]=t("本文由 ",-1)),l(r,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[9]||(a[9]=[t("LCTT",-1)])]),_:1}),a[12]||(a[12]=t(" 原创翻译，",-1)),l(r,{href:"http://linux.cn/"},{default:i(()=>[...a[10]||(a[10]=[t("Linux中国",-1)])]),_:1}),a[13]||(a[13]=t(" 荣誉推出",-1))])])}const b=n(_,[["render",d]]);export{g as __pageData,b as default};
